        ans += num_substrings * occ * (occ + 1) / 2;
    }

    cout << ans << endl;
    return 0;
}
```

Key points:
1. Each state i represents substrings with lengths in range (st[link[i]].len, st[i].len]
2. Number of unique substrings in state i = st[i].len - st[link[i]].len
3. All these substrings occur occ[i] times in the original string
4. Each contributes occ[i] * (occ[i] + 1) / 2 to the answer
5. Clone states start with occ = 0, original states start with occ = 1
6. Propagate occurrences through suffix links in reverse topological order (by decreasing length)

final_output:
```cpp
#include <bits/stdc++.h>
using namespace std;

struct State {
    int len, link;
    map<char, int> next;
    long long occ;
};

const int MAXN = 200005;
State st[MAXN];
int sz, last;

void sa_init() {
    st[0].len = 0;
    st[0].link = -1;
    st[0].occ = 0;
    st[0].next.clear();
    sz = 1;
    last = 0;
}

void sa_extend(char c) {
    int cur = sz++;
    st[cur].len = st[last].len + 1;
    st[cur].occ = 1;
    st[cur].next.clear();

    int p = last;
    while (p != -1 && st[p].next.find(c) == st[p].next.end()) {
        st[p].next[c] = cur;
        p = st[p].link;
    }

    if (p == -1) {
        st[cur].link = 0;
    } else {
        int q = st[p].next[c];
        if (st[p].len + 1 == st[q].len) {
            st[cur].link = q;
        } else {
            int clone = sz++;
            st[clone].len = st[p].len + 1;
            st[clone].next = st[q].next;
            st[clone].link = st[q].link;
            st[clone].occ = 0;
            while (p != -1 && st[p].next[c] == q) {
                st[p].next[c] = clone;
                p = st[p].link;
            }
            st[q].link = st[cur].link = clone;
        }
    }
    last = cur;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    cin >> s;

    sa_init();
    for (char c : s) {
        sa_extend(c);
    }

    vector<int> order(sz);
    for (int i = 0; i < sz; i++) order[i] = i;
    sort(order.begin(), order.end(), [](int a, int b) {
        return st[a].len > st[b].len;
    });

    for (int i = 0; i < sz; i++) {
        int v = order[i];
        if (st[v].link != -1) {
            st[st[v].link].occ += st[v].occ;
        }
    }

    long long ans = 0;
    for (int i = 1; i < sz; i++) {
        long long num_substrings = st[i].len - st[st[i].link].len;
        long long occ = st[i].occ;
        ans += num_substrings * occ * (occ + 1) / 2;
    }

    cout << ans << endl;
    return 0;
}
